    """
    This is a class for a calculator, capable of performing basic arithmetic calculations on numerical expressions using the operators +, -, *, /, and ^ (exponentiation).
    """

    def __init__(self):
        """
        Initialize the operations performed by the five operators'+','-','*','/','^'
        """
        self.operators = {
            '+': lambda x, y: x + y,
            '-': lambda x, y: x - y,
            '*': lambda x, y: x * y,
            '/': lambda x, y: x / y,
            '^': lambda x, y: x ** y
        }

    def calculate(self, expression):
        """
        Calculate the value of a given expression
        :param expression: string, given expression
        :return:If successful, returns the value of the expression; otherwise, returns None
        >>> calculator = Calculator()
        >>> calculator.calculate('1+2-3')
        0.0
        """
        if expression is None or not isinstance(expression, str):
            return None

        expression = expression.replace(" ", "")
        if not expression:
            return None

        operand_stack = []
        operator_stack = []

        i = 0
        n = len(expression)

        def is_unary_minus(idx):
            if expression[idx] != '-':
                return False
            if idx == 0:
                return True
            prev = expression[idx - 1]
            return prev in self.operators

        while i < n:
            ch = expression[i]

            if ch.isdigit() or ch == '.' or is_unary_minus(i):
                start = i
                if ch == '-':
                    i += 1
                    if i >= n:
                        return None
                dot_count = 0
                has_digit = False
                while i < n and (expression[i].isdigit() or expression[i] == '.'):
                    if expression[i] == '.':
                        dot_count += 1
                        if dot_count > 1:
                            return None
                    else:
                        has_digit = True
                    i += 1

                token = expression[start:i]
                if token in ('-', '.', '-.') or not has_digit:
                    return None
                try:
                    operand_stack.append(float(token))
                except ValueError:
                    return None
                continue

            if ch in self.operators:
                while operator_stack:
                    top = operator_stack[-1]
                    if (self.precedence(top) > self.precedence(ch)) or (
                        self.precedence(top) == self.precedence(ch) and ch != '^'
                    ):
                        operand_stack, operator_stack = self.apply_operator(operand_stack, operator_stack)
                        if operand_stack is None:
                            return None
                    else:
                        break
