    """
    This is a class that provides methods for decryption, including the Caesar cipher, Vigenere cipher, and Rail Fence cipher.
    """

    def __init__(self, key):
        """
        Initializes the decryption utility with a key.
        :param key: The key to use for decryption,str.
        """
        self.key = key if key is not None else ""

    def caesar_decipher(self, ciphertext, shift):
        """
        Deciphers the given ciphertext using the Caesar cipher
        :param ciphertext: The ciphertext to decipher,str.
        :param shift: The shift to use for decryption,int.
        :return: The deciphered plaintext,str.
        >>> d = DecryptionUtils('key')
        >>> d.caesar_decipher('ifmmp', 1)
        'hello'

        """
        if ciphertext is None:
            return ""
        if not isinstance(ciphertext, str):
            ciphertext = str(ciphertext)

        if shift is None:
            shift = 0
        try:
            shift = int(shift)
        except (TypeError, ValueError):
            shift = 0

        result = []
        shift = shift % 26

        for ch in ciphertext:
            if 'a' <= ch <= 'z':
                result.append(chr((ord(ch) - ord('a') - shift) % 26 + ord('a')))
            elif 'A' <= ch <= 'Z':
                result.append(chr((ord(ch) - ord('A') - shift) % 26 + ord('A')))
            else:
                result.append(ch)

        return ''.join(result)

    def vigenere_decipher(self, ciphertext):
        """
        Deciphers the given ciphertext using the Vigenere cipher
        :param ciphertext: The ciphertext to decipher,str.
        :return: The deciphered plaintext,str.
        >>> d = DecryptionUtils('key')
        >>> d.vigenere_decipher('ifmmp')
        'ybocl'

        """
        if ciphertext is None:
            return ""
        if not isinstance(ciphertext, str):
            ciphertext = str(ciphertext)

        key = self.key if self.key is not None else ""
        if not isinstance(key, str):
            key = str(key)

        key_letters = [c.lower() for c in key if c.isalpha()]
        if not key_letters:
            return ciphertext

        result = []
        key_index = 0
        key_len = len(key_letters)

        for ch in ciphertext:
            if ch.isalpha():
                k = ord(key_letters[key_index % key_len]) - ord('a')
                if 'a' <= ch <= 'z':
                    result.append(chr((ord(ch) - ord('a') - k) % 26 + ord('a')))
                else:
                    result.append(chr((ord(ch) - ord('A') - k) % 26 + ord('A')))
                key_index += 1
            else:
                result.append(ch)

        return ''.join(result)

    def rail_fence_decipher(self, encrypted_text, rails):
        """
        Deciphers the given ciphertext using the Rail Fence cipher
        :param encrypted_text: The ciphertext to decipher,str.
        :param rails: The number of rails to use for decryption,int.
        :return: The deciphered plaintext,str.
        >>> d = DecryptionUtils('key')
        >>> d.rail_fence_decipher('Hoo!el,Wrdl l', 3)
        'Hello, World!'

        """
        if encrypted_text is None:
            return ""
        if not isinstance(encrypted_text, str):
            encrypted_text = str(encrypted_text)

        if rails is None:
            rails = 2
        try:
            rails = int(rails)
        except (TypeError, ValueError):
            rails = 2

        n = len(encrypted_text)
        if n == 0:
            return ""
        if rails <= 1 or rails >= n:
            return encrypted_text

        pattern = []
        row = 0
        direction = 1
        for _ in range(n):
            pattern.append(row)
            if row == 0:
                direction = 1
            elif row == rails - 1:
                direction = -1
            row += direction

        counts = [0] * rails
        for r in pattern:
            counts[r] += 1

        rails_data = []
        idx = 0
        for c in counts:
            rails_data.append(list(encrypted_text[idx:idx + c]))
            idx += c

        rail_positions = [0] * rails
        result = []
        for r in pattern:
            result.append(rails_data[r][rail_positions[r]])
            rail_positions[r] += 1

        return ''.join(result)

